"""Locked pilot-only procedure for the boost route.

Screen: features kept in >= 50% of 200 half-resample top-30-F rankings
(vote_lib.stab_screen, thr=0.5), fitted once on the whole pilot sample and then
frozen — a screen fitted on pilot data alone. Model: HistGradientBoostingClassifier,
hyper-parameters tuned by cross-validation on pilot data alone.

data/heldout.csv is only ever read by analysis.py's final scoring step.
"""
import numpy as np
from sklearn.ensemble import HistGradientBoostingClassifier
from sklearn.metrics import roc_auc_score
from sklearn.model_selection import StratifiedKFold

from vote_lib import stab_screen

SEEDS = (0, 1, 2)
N_FOLDS = 5
N_INNER = 4
SCREEN = {"thr": 0.5, "B": 200, "seed": 0, "K": 30, "cap": 50}
GBM_FIXED = {"max_iter": 200, "max_bins": 64}
GRID = [
    {"learning_rate": lr, "max_leaf_nodes": leaves, "min_samples_leaf": 5}
    for lr in (0.05, 0.1)
    for leaves in (15, 31)
]


def load(path):
    tab = np.loadtxt(path, delimiter=",", skiprows=1)
    return tab[:, :-1], tab[:, -1]


def screen_features(X, y):
    return stab_screen(X, y, **SCREEN)


def make_gbm(p):
    return HistGradientBoostingClassifier(
        early_stopping=False, random_state=0, **GBM_FIXED, **p)


def fold_aucs(Xs, y, p, seeds=SEEDS, n_folds=N_FOLDS):
    aucs = []
    for seed in seeds:
        skf = StratifiedKFold(n_folds, shuffle=True, random_state=seed)
        for tr, te in skf.split(Xs, y):
            m = make_gbm(p).fit(Xs[tr], y[tr])
            aucs.append(roc_auc_score(y[te], m.predict_proba(Xs[te])[:, 1]))
    return np.array(aucs)


def tune_grid(Xs, y):
    """CV AUC of every grid config on the locked screen, best first."""
    scored = []
    for p in GRID:
        aucs = fold_aucs(Xs, y, p)
        scored.append({"params": p, "mean": round(float(aucs.mean()), 4),
                       "sd": round(float(aucs.std()), 4)})
    scored.sort(key=lambda r: -r["mean"])
    return scored


def nested_cv(Xs, y, seeds=SEEDS, n_out=N_FOLDS, n_in=N_INNER):
    """Honest estimate: the grid is retuned inside every outer fold."""
    outer, picks = [], []
    for seed in seeds:
        skf = StratifiedKFold(n_out, shuffle=True, random_state=seed)
        for tr, te in skf.split(Xs, y):
            inner = StratifiedKFold(n_in, shuffle=True, random_state=seed)
            best, best_auc = None, -1.0
            for p in GRID:
                scores = []
                for itr, ite in inner.split(Xs[tr], y[tr]):
                    m = make_gbm(p).fit(Xs[tr][itr], y[tr][itr])
                    pred = m.predict_proba(Xs[tr][ite])[:, 1]
                    scores.append(roc_auc_score(y[tr][ite], pred))
                if np.mean(scores) > best_auc:
                    best_auc, best = float(np.mean(scores)), p
            m = make_gbm(best).fit(Xs[tr], y[tr])
            pred = m.predict_proba(Xs[te])[:, 1]
            outer.append(roc_auc_score(y[te], pred))
            picks.append((best["learning_rate"], best["max_leaf_nodes"]))
    return np.array(outer), picks
